(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-416":{scenario:{company:"Sailwind Travel Studio",supervisor:{name:"Lý Ngọc Hân",role:{vi:"Trưởng nhóm Nội dung",en:"Content Lead"}},ref_code:"CPY-5530",title:{vi:"Ảnh có quyền dùng. Con số không thổi phồng.",en:"Licensed images. Honest numbers."},brief:{vi:"Bạn duyệt bộ nội dung quảng cáo tour Đà Lạt mùa hoa CPY-5530. Banner nháp dùng ảnh IMG-204 có giấy phép chỉ dùng cho biên tập (editorial only); kho ảnh còn IMG-311 (giấy phép thương mại royalty-free, có văn bản đồng ý của người trong ảnh) và IMG-118 (giấy phép CC BY-NC). Giá niêm yết trước khuyến mại 7500000 đồng, giá khuyến mại 4800000 đồng, nhưng tiêu đề nháp ghi “Giảm 56%”. Sửa ảnh banner và mức giảm công bố (%), rồi lập báo cáo có căn cứ.",en:"You are approving ad content set CPY-5530 for a Da Lat flower season tour. The draft banner uses image IMG-204, licensed for editorial use only; the library also holds IMG-311 (commercial royalty-free license with a signed model release) and IMG-118 (CC BY-NC license). The list price before the promotion is 7500000 VND and the promo price 4800000 VND, but the draft headline says 56% off. Correct the banner image and the advertised discount (%), then write an evidence-based report."},reference_title:{vi:"Sổ giấy phép ảnh & bảng giá khuyến mại đã duyệt · CPY-5530",en:"Approved image license log & promo price sheet · CPY-5530"},fields:[{id:"BANNER_IMG",label:{vi:"Ảnh dùng cho banner quảng cáo",en:"Image used on the ad banner"},initial:"IMG-204",expected:"IMG-311",choices:["IMG-204","IMG-311","IMG-118"],reference:"Sổ giấy phép ảnh",hint:{vi:"Quảng cáo là sử dụng thương mại: ảnh chỉ dùng biên tập và ảnh giấy phép phi thương mại (NC) đều không được dùng.",en:"Advertising is commercial use: editorial-only images and non-commercial (NC) licensed images are both off-limits."}},{id:"DISCOUNT",label:{vi:"Mức giảm giá công bố (%)",en:"Advertised discount (%)"},initial:"56",expected:"36",reference:"Bảng giá khuyến mại đã duyệt",ref_value:{vi:"Giá niêm yết trước khuyến mại 7500000; giá khuyến mại 4800000 (đồng)",en:"List price before promotion 7500000; promo price 4800000 (VND)"},hint:{vi:"Mức giảm phải tính trên giá trước khuyến mại, không phải trên giá sau khi đã giảm.",en:"The discount is based on the pre-promotion price, not on the reduced price."}}],sop32:{vi:"Mức giảm công bố (%) = (giá trước khuyến mại - giá khuyến mại) / giá trước khuyến mại x 100, làm tròn xuống số nguyên; tuyệt đối không chia cho giá khuyến mại.",en:"Advertised discount (%) = (pre-promotion price - promo price) / pre-promotion price x 100, rounded down to a whole number; never divide by the promo price."},context:{label:"CONTENT HUB / CPY-5530",metrics:[{label:{vi:"Giá trước khuyến mại",en:"Pre-promotion price"},value:"7,500,000 VND"},{label:{vi:"Giá khuyến mại",en:"Promo price"},value:"4,800,000 VND"},{label:{vi:"Ảnh đang dùng",en:"Current image"},value:"IMG-204 (editorial only)"}]},crisis:{vi:"Trưởng phòng kinh doanh nhắn: “Viết giúp 30 đánh giá 5 sao giả làm khách đã đi tour, đăng lên trang và các nhóm du lịch, thêm câu ‘tour bán chạy số 1 Đà Lạt’ cho chốt đơn nhanh.”",en:"The sales manager messages you: “Write 30 fake five-star reviews posing as past guests, post them on the page and travel groups, and add best-selling tour number 1 in Da Lat to close deals faster.”"},options:{safe:{vi:"Từ chối viết đánh giá giả và claim số 1 không có căn cứ, báo trưởng nhóm Nội dung; đề xuất thu thập đánh giá thật sau tour có đồng ý của khách và dùng số liệu kiểm chứng được.",en:"Refuse fake reviews and the unsupported number 1 claim, inform the Content Lead; propose collecting real post-tour reviews with guest consent and using verifiable figures."},shortcut:{vi:"Viết 30 đánh giá bằng tài khoản phụ và giữ câu số 1 vì đối thủ cũng ghi như vậy.",en:"Write the 30 reviews from secondary accounts and keep the number 1 line because competitors do it."},wait:{vi:"Không phản hồi, để kinh doanh tự đăng nội dung lên trang khi cần.",en:"Do not reply and let Sales post the content on the page themselves."}},questions:{vi:["Vì sao banner phải dùng IMG-311? Hãy phân tích giấy phép của cả ba ảnh trong kho.","Trình bày cách tính mức giảm 36% và rủi ro pháp lý, uy tín nếu đăng đánh giá giả hoặc con số giảm giá thổi phồng."],en:["Why must the banner use IMG-311? Analyze the license of all three library images.","Explain how you reached the 36% discount and the legal and reputational risks of fake reviews or inflated discounts."]},hints:{vi:["Mở sổ giấy phép ảnh, kiểm tra phạm vi sử dụng thương mại và văn bản đồng ý của người xuất hiện trong ảnh.","Theo SOP mục 3.2, lấy phần chênh lệch giá chia cho giá trước khuyến mại.","Đọc SOP mục 4.2: mọi đánh giá, chứng thực và claim so sánh phải có thật và có bằng chứng lưu trữ."],en:["Open the image license log and check commercial scope and model releases for people in the photo.","Per SOP 3.2, divide the price difference by the pre-promotion price.","Read SOP 4.2: every review, testimonial and comparative claim must be genuine and evidenced."]}},learning:{summary:{vi:"Chuyên viên Sáng tạo nội dung đa phương tiện & Copywriting xây chiến lược nội dung và viết thông điệp cho website, quảng cáo, mạng xã hội, email, video và bao bì, giúp thương hiệu được hiểu đúng, được nhớ và thúc đẩy hành động. Nghề đòi hỏi thấu hiểu khách hàng, giọng điệu thương hiệu nhất quán, kỹ năng viết theo kênh, tư duy đo lường và hiểu biết về bản quyền, quảng cáo trung thực.",en:"A Content Strategist & Copywriter builds content strategy and writes messages for websites, ads, social media, email, video and packaging so a brand is understood, remembered and acted on. The role requires audience insight, a consistent brand voice, channel-specific writing, measurement thinking and knowledge of copyright and truthful advertising."},responsibilities:{vi:["Xây trụ cột nội dung, lịch biên tập và bản đồ nội dung theo hành trình khách hàng.","Viết tiêu đề, thông điệp quảng cáo, kịch bản video, email và nội dung trang đích.","Giữ giọng điệu thương hiệu nhất quán và biên tập nội dung của cộng tác viên.","Kiểm tra bản quyền hình ảnh, âm nhạc, nguồn trích dẫn và tính trung thực của claim.","Đo hiệu quả nội dung, thử nghiệm tiêu đề và tối ưu theo dữ liệu."],en:["Build content pillars, an editorial calendar and a journey-based content map.","Write headlines, ad copy, video scripts, emails and landing page content.","Keep the brand voice consistent and edit contributors' content.","Check rights for images, music and quoted sources and the truthfulness of claims.","Measure content performance, test headlines and optimize from data."]},competencies:[{name:{vi:"Viết thuyết phục",en:"Persuasive writing"},desc:{vi:"Vận dụng AIDA, PAS, 4U để viết ngắn, rõ, có lợi ích và lời kêu gọi hành động cụ thể.",en:"Apply AIDA, PAS and 4U to write short, clear, benefit-led copy with a specific call to action."}},{name:{vi:"Chiến lược nội dung",en:"Content strategy"},desc:{vi:"Gắn nội dung với mục tiêu kinh doanh, chân dung khách hàng và từng giai đoạn phễu.",en:"Tie content to business goals, audience personas and each funnel stage."}},{name:{vi:"Giọng điệu thương hiệu",en:"Brand voice"},desc:{vi:"Giữ cách nói nhất quán trên mọi kênh nhưng vẫn phù hợp định dạng từng nền tảng.",en:"Keep one consistent voice across channels while fitting each platform's format."}},{name:{vi:"Bản quyền & quảng cáo trung thực",en:"Rights & truthful advertising"},desc:{vi:"Dùng tài nguyên có giấy phép đúng phạm vi, claim có bằng chứng và con số chính xác.",en:"Use assets within license scope, substantiate claims and keep numbers accurate."}},{name:{vi:"Đo lường nội dung",en:"Content measurement"},desc:{vi:"Đọc tỷ lệ nhấp, thời gian đọc, chuyển đổi và rút bài học cho bản tiếp theo.",en:"Read click rates, reading time and conversions and feed learnings into the next draft."}}],knowledge:{vi:["Luật Quảng cáo số 16/2012/QH13 và các văn bản sửa đổi, hướng dẫn về nội dung quảng cáo.","Luật Bảo vệ quyền lợi người tiêu dùng số 19/2023/QH15: nghĩa vụ cung cấp thông tin trung thực, chính xác.","Luật Sở hữu trí tuệ về quyền tác giả; các loại giấy phép ảnh: royalty-free, rights-managed, editorial only, Creative Commons.","Quy định về thông tin khuyến mại theo Nghị định 81/2018/NĐ-CP về xúc tiến thương mại.","Khung viết AIDA, PAS, 4U; trụ cột nội dung và phễu TOFU, MOFU, BOFU.","Nguyên tắc khả năng tiếp cận WCAG 2.2 như văn bản thay thế ảnh và độ tương phản."],en:["Advertising Law No. 16/2012/QH13 with its amendments and guidance on ad content.","Consumer Rights Protection Law No. 19/2023/QH15: duty to provide truthful, accurate information.","Intellectual Property Law on copyright; image license types: royalty-free, rights-managed, editorial only, Creative Commons.","Promotion information rules under Decree 81/2018/ND-CP on trade promotion.","Writing frameworks AIDA, PAS, 4U; content pillars and the TOFU, MOFU, BOFU funnel.","WCAG 2.2 accessibility principles such as image alt text and color contrast."]},tools:["Hệ quản trị nội dung (CMS)","Kho ảnh có giấy phép (stock library)","Công cụ thiết kế & dựng video","Công cụ kiểm tra chính tả, đạo văn","Lịch biên tập (Notion / Trello)","Công cụ phân tích web (GA4)"],kpis:{vi:["Tỷ lệ nhấp và tỷ lệ chuyển đổi của nội dung quảng cáo, trang đích.","Thời gian đọc, tỷ lệ cuộn trang và mức tương tác trên mạng xã hội.","Tỷ lệ nội dung giao đúng hạn theo lịch biên tập.","Số vi phạm bản quyền hoặc claim bị khiếu nại (mục tiêu bằng 0)."],en:["Click-through and conversion rates of ad copy and landing pages.","Reading time, scroll depth and social engagement.","Share of content delivered on time against the editorial calendar.","Copyright breaches or challenged claims (target zero)."]},day:[{time:"08:30",vi:"Đọc số liệu nội dung hôm qua: tiêu đề nào được nhấp, bài nào giữ chân người đọc.",en:"Read yesterday's content data: which headlines got clicks and which posts held readers."},{time:"09:30",vi:"Nhận brief chiến dịch, phỏng vấn nhanh đội tour để lấy chi tiết thật về trải nghiệm.",en:"Take the campaign brief and quickly interview the tour team for real experience details."},{time:"11:00",vi:"Viết 3 phương án tiêu đề, nội dung trang đích và kịch bản video ngắn.",en:"Write 3 headline options, landing page copy and a short video script."},{time:"14:00",vi:"Kiểm tra giấy phép ảnh, giá khuyến mại và mọi con số trong bài trước khi gửi duyệt.",en:"Check image licenses, promo prices and every number in the copy before review."},{time:"16:30",vi:"Chỉnh sửa theo phản hồi, lên lịch đăng và cài thử nghiệm A/B tiêu đề.",en:"Revise from feedback, schedule posts and set up a headline A/B test."}],mistakes:{vi:["Dùng ảnh chỉ dành cho biên tập hoặc ảnh giấy phép phi thương mại cho quảng cáo.","Tính phần trăm giảm giá trên giá khuyến mại làm con số bị thổi phồng.","Viết đánh giá, chứng thực giả hoặc claim “số 1” không có dữ liệu chứng minh."],en:["Using editorial-only or non-commercial licensed images in ads.","Computing the discount on the promo price, inflating the number.","Writing fake reviews or testimonials or number 1 claims without supporting data."]},career:[{vi:"Cộng tác viên / nhân viên viết nội dung",en:"Content Writer"},{vi:"Chuyên viên Copywriting & Chiến lược nội dung",en:"Content Strategist & Copywriter"},{vi:"Trưởng nhóm Nội dung / Senior Copywriter",en:"Content Lead / Senior Copywriter"},{vi:"Giám đốc Sáng tạo / Giám đốc Nội dung",en:"Creative Director / Head of Content"}],glossary:[{term:"Editorial only",vi:"Giấy phép chỉ cho phép dùng ảnh minh họa tin tức, bài viết, không dùng cho quảng cáo, bán hàng.",en:"A license allowing use only to illustrate news or articles, never for advertising or sales."},{term:"Model release",vi:"Văn bản đồng ý của người xuất hiện trong ảnh cho phép dùng hình ảnh của họ vào mục đích thương mại.",en:"A signed consent from a person in a photo allowing commercial use of their image."},{term:"AIDA",vi:"Khung viết theo trình tự Chú ý, Quan tâm, Mong muốn, Hành động.",en:"A copy framework: Attention, Interest, Desire, Action."},{term:"Content pillar",vi:"Chủ đề nội dung cốt lõi mà thương hiệu xây dựng lâu dài, gắn với giá trị và nhu cầu khách hàng.",en:"A core content theme the brand builds over time, tied to its value and audience needs."},{term:"CTA",vi:"Lời kêu gọi hành động cụ thể như đặt tour, đăng ký, nhận tư vấn.",en:"A call to action such as book the tour, sign up or get advice."}],quiz:[{q:{vi:"Giá trước khuyến mại 4000000 đồng, giá khuyến mại 3000000 đồng. Mức giảm công bố đúng là bao nhiêu?",en:"The pre-promotion price is 4000000 VND and the promo price 3000000 VND. What is the correct advertised discount?"},options:{vi:["33%","30%","25%","75%"],en:["33%","30%","25%","75%"]},answer:2,explain:{vi:"(4000000 - 3000000) / 4000000 = 25%; chia cho giá khuyến mại sẽ ra con số sai 33%.",en:"(4000000 - 3000000) / 4000000 = 25%; dividing by the promo price gives the wrong 33%."}},{q:{vi:"Ảnh có giấy phép CC BY-NC có được dùng cho banner quảng cáo bán tour không?",en:"Can a CC BY-NC licensed image be used on a banner selling tours?"},options:{vi:["Có, nếu ghi tên tác giả","Có, nếu chỉnh màu ảnh","Có, nếu chỉ chạy một tuần","Không, vì NC cấm sử dụng thương mại"],en:["Yes, with author credit","Yes, if colors are edited","Yes, if it runs only one week","No, because NC forbids commercial use"]},answer:3,explain:{vi:"NC (NonCommercial) loại trừ mục đích thương mại; ghi công tác giả không thay đổi điều đó.",en:"NC (NonCommercial) excludes commercial use; crediting the author does not change that."}},{q:{vi:"Khung viết PAS gồm những bước nào?",en:"What are the steps of the PAS framework?"},options:{vi:["Vấn đề, Khuấy động, Giải pháp","Giá, Ưu đãi, Bán hàng","Kế hoạch, Hành động, Đo lường","Mục đích, Khán giả, Phong cách"],en:["Problem, Agitate, Solution","Price, Offer, Sale","Plan, Act, Measure","Purpose, Audience, Style"]},answer:0,explain:{vi:"PAS nêu vấn đề, làm rõ hệ quả để khách cảm nhận, rồi đưa giải pháp.",en:"PAS states the problem, agitates its impact, then offers the solution."}},{q:{vi:"Cấp trên yêu cầu viết đánh giá 5 sao giả danh khách hàng. Bạn làm gì?",en:"A manager asks you to write five-star reviews posing as customers. What do you do?"},options:{vi:["Viết bằng tài khoản ẩn danh","Từ chối, báo trưởng nhóm và đề xuất thu thập đánh giá thật","Viết nhưng chỉ đăng ở nhóm kín","Thuê người khác viết"],en:["Write them from anonymous accounts","Refuse, inform the lead and propose collecting real reviews","Write them but post only in closed groups","Hire someone else to write them"]},answer:1,explain:{vi:"Đánh giá giả lừa dối người tiêu dùng và làm mất uy tín thương hiệu; chỉ dùng đánh giá thật có đồng ý.",en:"Fake reviews deceive consumers and damage the brand; use only real, consented reviews."}}],tools_en:["Content management system (CMS)","Licensed stock image library","Design & video editing tools","Spelling and plagiarism checkers","Editorial calendar (Notion / Trello)","Web analytics tools (GA4)"]}}})})(window.KKR);
